function saveWithoutRide(){try{app.wizard.Omschrijving=app.wizard.Omschrijving||'';app.wizard.step=8;app.wizard.hasRide=false;app.wizard.Km='';saveWizardNoRide();}catch(e){notify(e.message,true);}}
function saveWizardNoRide(){if(!requireLogin())return;let w=app.wizard;w.step=8;/* saveWizard requires an input on step 8: use a transient skip to avoid mileage validation */let oldStep=w.step;w.step=4;let node=$('wizValue');let saved=node?.value;/* leave read at step 4 harmless */w.step=oldStep;let now=new Date().toISOString();let old=w.id?app.db.Registraties.find(r=>r.Id===w.id):null;let record={Id:old?.Id||uid(),Datum:w.Datum,Begintijd:old?.Begintijd||'',Eindtijd:old?.Eindtijd||'',Projectnummer:w.Projectnummer,Activiteit:w.Activiteit,Omschrijving:w.Omschrijving,Uren:round(num(w.Uren)),SoortUren:w.SoortUren||'DIRECT',VanPostcode:'',NaarPostcode:'',Retour:'',Km:0,ReistijdMinuten:0,KmMethode:'',OdometerBegin:'',OdometerEind:'',WerkelijkVertrek:'',WerkelijkeBestemming:'',RouteOpmerking:'',FacturatieStatus:old?.FacturatieStatus||'open',VroegerGedeclareerdeUren:old?.VroegerGedeclareerdeUren||0,BronMaand:old?.BronMaand||monthOf(w),BronRij:old?.BronRij||'',Aangemaakt:old?.Aangemaakt||now,Gewijzigd:now};if(!w.Datum||!project(w.Projectnummer)||!w.Activiteit||num(w.Uren)<=0){notify('Registratie is niet volledig.',true);return;}if(old&&regHours(record)<num(old.VroegerGedeclareerdeUren)+allocations(old.Id)){notify('Er zijn meer uren gedeclareerd dan het nieuwe totaal.',true);return;}if(old){let prev={...old};Object.assign(old,record);audit('Gewijzigd','Registratie',old.Id,{voor:prev,na:record});}else{app.db.Registraties.push(record);audit('Toegevoegd','Registratie',record.Id,record.Datum);}app.month=monthOf(record);initWizard();app.showAllEntries=false;persist();render();notify('Registratie opgeslagen.',false,true);}
function init(){let y=Number(new Date().getFullYear());if([2026,2027].includes(y))app.year=y;app.agendaDate=app.year===y?today():`${app.year}-01-01`;app.db=initDB(app.year);app.cloud.dirty=hasPending(app.year);app.month=app.year===new Date().getFullYear()?new Date().getMonth()+1:1;app.dashboardMonth=app.year===new Date().getFullYear()?new Date().getMonth()+1:0;initWizard();$('year').innerHTML=Array.from({length:10},(_,i)=>2024+i).map(y=>`<option value="${y}" ${y===app.year?'selected':''}>${y}</option>`).join('');document.querySelector('.tabs').addEventListener('click',e=>{let tab=e.target.closest('[data-page]');if(tab&&app.cloud.connected){app.page=tab.dataset.page;eventRender();}});window.setInterval?.(()=>{const el=$('timerDisplay');if(el&&moduleEnabled('Stopwatch'))el.textContent=timerText(timerElapsed(timerRead()));},1000);document.body.addEventListener('submit',e=>{if(e.target.id==='stackLoginForm'){e.preventDefault();void connectCloud();}});document.body.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(el){e.preventDefault();clickAction(el.dataset.action,el);}if(e.target.classList.contains('dialog-backdrop'))closeModal();});document.body.addEventListener('change',e=>{let t=e.target;if(t.id!=='year'&&!app.cloud.connected)return;switch(t.id){case 'year':changeYear(Number(t.value));break;case 'moduleBudgets':if(!t.checked&&$('moduleWarnings'))$('moduleWarnings').checked=false;break;case 'moduleWarnings':if(t.checked&&$('moduleBudgets'))$('moduleBudgets').checked=true;break;case 'dashboardMonth':app.dashboardMonth=Number(t.value);render();break;case 'projectFilter':app.projectFilter=t.value;render();break;case 'billingProject':initializeBilling(t.value);render();break;case 'monthProjectFilter':app.monthProject=t.value;render();break;case 'agendaProjectFilter':app.agendaProject=t.value;render();break;case 'agendaKindFilter':app.agendaKind=t.value;render();break;case 'billMethod':app.billMethod=t.value;render();break;case 'importFile':importWorkbook(t.files?.[0]);break;case 'businessLogoFile':prepareLogo(t.files?.[0]).catch(e=>notify(e.message,true));break;case 'editHasRide':toggleEditRide();break;case 'billPercentage':app.billPercentage=num(t.value);render();break;case 'billBase':app.billBase=num(t.value);render();break;case 'billOverride':app.billOverride=t.value;render();break;default:break;}if(['editStartTime','editEndTime'].includes(t.id))syncEditDuration();if(['editFrom','editTo','editReturn'].includes(t.id))scheduleEditRoute();if(t.id==='editKm'){editRouteRun++;t.dataset.method='Handmatig';const msg=$('editRouteStatus');if(msg)msg.textContent='Handmatig aangepast';}if(t.dataset.billCheck){let id=t.dataset.billCheck;app.billHours[id]=t.checked?availableHours(app.db.Registraties.find(r=>r.Id===id)):0;render();}if(t.dataset.billHours){let id=t.dataset.billHours;let r=app.db.Registraties.find(r=>r.Id===id);app.billHours[id]=Math.min(Math.max(0,num(t.value)),availableHours(r));render();}});document.body.addEventListener('input',e=>{if(!app.cloud.connected)return;if(['editStartTime','editEndTime'].includes(e.target.id))syncEditDuration();if(['editFrom','editTo','editReturn'].includes(e.target.id))scheduleEditRoute();if(e.target.id==='editKm'){editRouteRun++;e.target.dataset.method='Handmatig';}if(e.target.id==='billReference')app.billReference=e.target.value;if(e.target.id==='billNote')app.billNote=e.target.value;if(e.target.id==='projectQuery'){let caret=e.target.selectionStart;app.projectQuery=e.target.value;render();let q=$('projectQuery');q?.focus();q?.setSelectionRange(caret,caret);}});document.body.addEventListener('keydown',e=>{if(app.cloud.connected&&e.key==='Enter'&&e.target.closest('.guided-input')&&e.target.tagName!=='TEXTAREA'&&!e.target.closest('button')){e.preventDefault();if(app.wizard.step!==5&&app.wizard.step!==8)wizardNext();else if(app.wizard.step===8)saveWizard();}});$('syncButton').addEventListener('click',()=>{if(app.cloud.connected){app.page='instellingen';eventRender();}else $('cloudPassword')?.focus();});window.addEventListener('beforeunload',e=>{if(app.cloud.connected&&(app.cloud.dirty||app.cloud.busy)){e.preventDefault();e.returnValue='';}});window.LAAgendaDrag?.install?.({element:document.body,onSelect:selection=>{if(app.cloud.connected&&app.page==='agenda')agendaNew({dataset:{date:selection.date,time:selection.start,end:selection.end}});}});eventRender();if(app.cloud.url&&app.cloud.password)void connectCloud({automatic:true});}
